export const BENCHMARK_VERSION = '1.0.0';
export const SCENARIOS: Scenario[] = DATA.map(item => ({...item, tools: TOOL_CATALOG}));

export function loadScenarios(tier?: Scenario['tier']): Scenario[] {
  return tier ? SCENARIOS.filter(s => s.tier === tier) : [...SCENARIOS];
}

export function allScenarios(): Scenario[] {
  return [...SCENARIOS];
}
